import fs from 'node:fs/promises';
const f=JSON.parse(await fs.readFile(new URL('../tests/fixtures/sirenic/catalog.json',import.meta.url),'utf8'));
const out=new URL('../supabase/migrations/20260912202445_sirenic_planner_source.sql',import.meta.url);
const q=v=>v==null?'NULL':`'${String(v).replaceAll("'","''")}'`;
const j=v=>`${q(JSON.stringify(v))}::jsonb`;
const id='804c77ce-bac1-4880-9e83-04f8b701b839';
const sql=[`-- Sirenic as a normal planner source; treasury x402, existing balance ledger + 15%.
-- Generated by scripts/render-sirenic-migration.mjs from reviewed official samples.
-- Requires the Sirenic USDC/payee guard in the embedded executor.
BEGIN;
SELECT pg_advisory_xact_lock(hashtext('sirenic-planner-source'));
DO $guard$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM providers.apis WHERE id='${id}' AND slug='sirenic' AND status='active' AND is_verified AND suspended_at IS NULL AND wallet_address ILIKE '0x76A672EEe56D29D475b0715cc03B8C99D70EC8A2') THEN RAISE EXCEPTION 'Sirenic reviewed identity changed'; END IF;
 IF EXISTS(SELECT 1 FROM catalog.capability_execution_contracts c JOIN providers.api_endpoints e ON e.id=c.endpoint_id WHERE e.api_id='${id}' AND c.id NOT IN (${f.services.map(s=>q(s.id)).join(',')})) THEN RAISE EXCEPTION 'Unexpected existing Sirenic contracts'; END IF;
END $guard$;
UPDATE providers.apis SET origin_url='https://api.sirenic.eu',endpoint_url='https://api.sirenic.eu',docs_url='https://api.sirenic.eu/openapi.json',website_url='https://sirenic.eu',discoverable=true,
 description='French and European company data from official registers: company search, registry profiles, French filed financial accounts and KYB.',
 listing_metadata=listing_metadata || ${j({resell:{enabled:true,source:'sirenic-reviewed-openapi-20260912'},implementation_type:'direct',hosted_externally:true,coverage_notice:'Six reviewed read routes: French and European search/profiles, French financials and KYB. Source provenance and financial quality flags apply; null is unpublished, never zero. Other routes, monitoring and variable-price batches are not enabled.'})}
 WHERE id='${id}';
-- Preserve old sample-specific rows for historical selections, but stop offering them.
UPDATE providers.api_endpoints SET active=false WHERE api_id='${id}' AND id NOT IN (${f.services.map(s=>q(s.endpoint_id)).join(',')});`];
for(const w of f.new_words) {
 sql.push(`INSERT INTO catalog.fact_types(slug,name,description,subject_kind,jurisdiction,value_schema,status,freshness_seconds) VALUES(${q(w.slug)},${q(w.name)},${q(w.description)},'company',${q(w.jurisdiction)},${j(w.value_schema)},'active',3600) ON CONFLICT(slug) DO NOTHING;
DO $guard$ BEGIN IF NOT EXISTS(SELECT 1 FROM catalog.fact_types WHERE slug=${q(w.slug)} AND status='active' AND value_schema=${j(w.value_schema)}) THEN RAISE EXCEPTION 'Sirenic fact schema conflict: %',${q(w.slug)}; END IF; END $guard$;`);
}
for(const c of f.capabilities) sql.push(`INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES(${q(c.slug)},${q(c.name)},${q(c.description)},'company',${j(c.input_contract)},${j(c.output_contract)},'active') ON CONFLICT(slug) DO NOTHING;`);
for(const e of f.endpoints) {
 sql.push(`INSERT INTO providers.api_endpoints(id,api_id,path,method,price,payment_required,active,description,query_params,response_body,response_example,tags,endpoint_category,metadata_source,metadata_at,network_token_id)
VALUES(${q(e.id)},'${id}',${q(e.path)},'GET',${e.price},true,true,${q(e.description)},${j(e.query_params)},'{"type":"object"}',${j(e.response_example)},ARRAY['company','registry','sirenic'],'company','openapi',now(),'26adabc5-92ec-44f3-9540-3bd636eeb1f4')
ON CONFLICT(id) DO UPDATE SET price=EXCLUDED.price,payment_required=true,active=true,description=EXCLUDED.description,query_params=EXCLUDED.query_params,response_body=EXCLUDED.response_body,response_example=EXCLUDED.response_example,tags=EXCLUDED.tags,endpoint_category=EXCLUDED.endpoint_category,metadata_source=EXCLUDED.metadata_source,metadata_at=EXCLUDED.metadata_at,network_token_id=EXCLUDED.network_token_id
WHERE api_endpoints.api_id=EXCLUDED.api_id AND api_endpoints.path=EXCLUDED.path AND api_endpoints.method=EXCLUDED.method;`);
}
for(const s of f.services) {
 const c=s.contract, produces=Object.keys(c.output_map.produces).map(fact_type=>({fact_type,subject_role:'subject',cardinality:c.cardinality}));
 sql.push(`INSERT INTO catalog.capability_execution_contracts(id,capability_slug,endpoint_id,version,status,requires,produces,input_map,fixed_params,output_map,cardinality,identifies,max_fan_out,preconditions,pagination,effect,price_model,freshness_seconds,sample_payload,validated_at,validated_note,notes)
VALUES(${q(s.id)},${q(c.capability_slug)},${q(s.endpoint_id)},1,'active',${j(c.requires)},${j(produces)},${j(c.input_map)},'{}',${j(c.output_map)},${q(c.cardinality)},${q(c.identifies)},1,'{}','{}','read','per_call',3600,${j(s.sample_payload)},now(),'Official OpenAPI samples and live unpaid quote; Rust contract extraction, planning, binding and pricing tests. Paid execution evidence recorded separately.','sirenic-20260912: retain full response provenance/quality; only fixed-price read routes') ON CONFLICT(id) DO NOTHING;
DO $guard$ BEGIN IF NOT EXISTS(SELECT 1 FROM catalog.capability_execution_contracts WHERE id=${q(s.id)} AND endpoint_id=${q(s.endpoint_id)} AND capability_slug=${q(c.capability_slug)} AND input_map=${j(c.input_map)} AND output_map=${j(c.output_map)} AND fixed_params='{}' AND status='active') THEN RAISE EXCEPTION 'Sirenic immutable contract conflict'; END IF; END $guard$;`);
}
sql.push(`DO $verify$ BEGIN
 IF (SELECT count(*) FROM providers.api_endpoints WHERE api_id='${id}' AND active)<>6 THEN RAISE EXCEPTION 'Expected six active Sirenic routes'; END IF;
END $verify$;
COMMIT;\n`);
const content=sql.join('\n\n');
if(process.argv.includes('--check')) {if(await fs.readFile(out,'utf8')!==content)throw Error('Sirenic migration drift');}
else await fs.writeFile(out,content);
console.log('Rendered six Sirenic contracts and corrected source routing');
// The historical import used POST for the two existing search IDs. The first
// migration deliberately refused a method mismatch; repair those exact rows.
const repair=new URL('../supabase/migrations/20260912202706_sirenic_search_request_methods.sql',import.meta.url);
const repairs=['-- Correct the two imported search rows (POST, missing schema, stale price).','BEGIN;'];
for(const e of f.endpoints.filter(e=>e.path.endsWith('/recherche'))) {
 repairs.push(`UPDATE providers.api_endpoints SET method='GET',price=${e.price},payment_required=true,active=true,description=${q(e.description)},query_params=${j(e.query_params)},response_body='{"type":"object"}',response_example=${j(e.response_example)},tags=ARRAY['company','registry','sirenic'],endpoint_category='company',metadata_source='openapi',metadata_at=now(),network_token_id='26adabc5-92ec-44f3-9540-3bd636eeb1f4'
WHERE id=${q(e.id)} AND api_id='${id}' AND path=${q(e.path)} AND method IN ('POST','GET');`);
}
for(const e of f.endpoints) repairs.push(`DO $verify$ BEGIN IF NOT EXISTS(SELECT 1 FROM providers.api_endpoints WHERE id=${q(e.id)} AND api_id='${id}' AND path=${q(e.path)} AND method='GET' AND price=${e.price} AND active AND query_params=${j(e.query_params)}) THEN RAISE EXCEPTION 'Sirenic request contract mismatch: %',${q(e.path)}; END IF; END $verify$;`);
repairs.push('COMMIT;\n');const fixed=repairs.join('\n\n');
if(process.argv.includes('--check')) {if(await fs.readFile(repair,'utf8')!==fixed)throw Error('Sirenic request repair drift');} else await fs.writeFile(repair,fixed);
